sys_variable_value.value:
(function execute(inputs, outputs) {
var count = 0;
if (inputs.records && Array.isArray(inputs.records)) {
    count = inputs.records.length;
}
var scheduleGR = new GlideRecord('x_1793782_traini_0_schedule');
    if (scheduleGR.get(inputs.schedule)) {
        var maxVacancies = parseInt(scheduleGR.getValue('max_vacancies'), 10) || 0;

            if (count > maxVacancies) {
                scheduleGR.setValue('max_vacancies', count);
                scheduleGR.update();
            }
    }

outputs.enrollment_count = parseInt(count);
})(inputs, outputs);

